using System.Security.Claims;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using SoodalLife.Api.Domain.Entities;
using SoodalLife.Api.Features.Admin;
using SoodalLife.Api.Features.Authentication;
using SoodalLife.Api.Infrastructure.Persistence;

namespace SoodalLife.Api.Features.Notifications;

public sealed class NotificationBroadcastService(SoodalLifeDbContext db,AdminSecurityService security,IEnumerable<INotificationChannelSender> senders)
{
    private static readonly string[] AllowedChannels=["WEB","KAKAO","SMS","EMAIL","PUSH"];
    public async Task<PagedNotificationBroadcasts> Search(int page,int pageSize,CancellationToken token){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,10,100);var q=db.NotificationBroadcasts.AsNoTracking();var count=await q.CountAsync(token);var rows=await q.OrderByDescending(x=>x.CreatedAt).Skip((page-1)*pageSize).Take(pageSize).ToListAsync(token);return new(rows.Select(Item).ToArray(),page,pageSize,count,Math.Max(1,(int)Math.Ceiling(count/(double)pageSize)));}
    public async Task<NotificationBroadcastItem> Detail(Guid id,CancellationToken token)=>Item(await db.NotificationBroadcasts.AsNoTracking().SingleOrDefaultAsync(x=>x.PublicId==id,token)??throw Error(404,"BROADCAST_NOT_FOUND","단체발송을 찾을 수 없습니다."));
    public async Task<NotificationBroadcastItem> Create(SaveNotificationBroadcastRequest input,ClaimsPrincipal principal,CancellationToken token){var actor=await Actor(principal,token);Validate(input);var now=DateTime.UtcNow;var row=new NotificationBroadcast{Name=input.Name.Trim(),AudienceCode=Audience(input.AudienceCode),KindCode=Kind(input.KindCode),ChannelsJson=JsonSerializer.Serialize(Channels(input)),Title=input.Title.Trim(),Body=input.Body.Trim(),ScheduledAt=input.ScheduledAt?.ToUniversalTime(),StatusCode="DRAFT",CreatedAt=now,CreatedByUserId=actor,UpdatedAt=now,UpdatedByUserId=actor};db.NotificationBroadcasts.Add(row);await db.SaveChangesAsync(token);Audit(actor,"NOTIFICATION_BROADCAST_CREATED",row.PublicId,new{row.AudienceCode,row.KindCode});await db.SaveChangesAsync(token);return Item(row);}
    public async Task<NotificationBroadcastItem> Update(Guid id,SaveNotificationBroadcastRequest input,ClaimsPrincipal principal,CancellationToken token){var actor=await Actor(principal,token);Validate(input);var row=await db.NotificationBroadcasts.SingleOrDefaultAsync(x=>x.PublicId==id,token)??throw Error(404,"BROADCAST_NOT_FOUND","단체발송을 찾을 수 없습니다.");if(row.StatusCode!="DRAFT")throw Error(409,"BROADCAST_NOT_EDITABLE","작성 중인 단체발송만 수정할 수 있습니다.");Version(row,input.RowVersion);row.Name=input.Name.Trim();row.AudienceCode=Audience(input.AudienceCode);row.KindCode=Kind(input.KindCode);row.ChannelsJson=JsonSerializer.Serialize(Channels(input));row.Title=input.Title.Trim();row.Body=input.Body.Trim();row.ScheduledAt=input.ScheduledAt?.ToUniversalTime();row.PreviewedAt=null;row.EstimatedAudienceCount=0;row.UpdatedAt=DateTime.UtcNow;row.UpdatedByUserId=actor;await Save(token);return Item(row);}
    public async Task<NotificationBroadcastPreview> Preview(Guid id,ClaimsPrincipal principal,CancellationToken token){var actor=await Actor(principal,token);var row=await db.NotificationBroadcasts.SingleOrDefaultAsync(x=>x.PublicId==id,token)??throw Error(404,"BROADCAST_NOT_FOUND","단체발송을 찾을 수 없습니다.");if(row.StatusCode!="DRAFT")throw Error(409,"BROADCAST_NOT_PREVIEWABLE","작성 중인 단체발송만 미리 볼 수 있습니다.");var total=await db.Users.AsNoTracking().CountAsync(x=>x.StatusCode=="ACTIVE",token);var baseQuery=AudienceUsers(row.AudienceCode);var audience=await baseQuery.CountAsync(token);var relevantRoles=row.AudienceCode=="ALL"?new[]{RoleCodes.Customer,RoleCodes.Provider}:new[]{row.AudienceCode};var roleLinks=await(from ur in db.UserRoles.AsNoTracking()join role in db.Roles.AsNoTracking()on ur.RoleId equals role.Id where ur.RevokedAt==null&&role.IsActive&&relevantRoles.Contains(role.Code)select ur.UserId).CountAsync(token);var counts=new Dictionary<string,int>();foreach(var channel in ParseChannels(row.ChannelsJson)){var count=0;await foreach(var userId in baseQuery.OrderBy(x=>x.Id).Select(x=>x.Id).AsAsyncEnumerable().WithCancellation(token))if(await CanDeliverAsync(row,userId,channel,row.ScheduledAt??DateTime.UtcNow,token))count++;counts[channel]=count;}row.EstimatedAudienceCount=audience;row.PreviewedAt=DateTime.UtcNow;row.UpdatedAt=DateTime.UtcNow;row.UpdatedByUserId=actor;await db.SaveChangesAsync(token);return new(total,counts,total-audience,Math.Max(0,roleLinks-audience),row.PreviewedAt.Value);}
    public async Task<NotificationBroadcastItem> Confirm(Guid id,ConfirmNotificationBroadcastRequest input,ClaimsPrincipal principal,string? reauth,CancellationToken token){var actorPublic=Principal(principal);var actor=await security.RequireSensitiveAccessAsync(actorPublic,reauth,AdminDetailRoles.SuperAdmin,AdminDetailRoles.Operations,AdminDetailRoles.Content);var row=await db.NotificationBroadcasts.SingleOrDefaultAsync(x=>x.PublicId==id,token)??throw Error(404,"BROADCAST_NOT_FOUND","단체발송을 찾을 수 없습니다.");if(row.StatusCode!="DRAFT")throw Error(409,"BROADCAST_ALREADY_CONFIRMED","이미 확정되거나 취소된 단체발송입니다.");Version(row,input.RowVersion);if(input.ConfirmationText.Trim()!="발송 확인")throw Error(409,"BROADCAST_CONFIRMATION_REQUIRED","2차 확인 문구로 ‘발송 확인’을 입력해 주세요.");if(row.PreviewedAt is null||row.PreviewedAt<DateTime.UtcNow.AddMinutes(-30))throw Error(409,"BROADCAST_PREVIEW_REQUIRED","대상 미리보기를 다시 확인한 후 발송을 확정해 주세요.");var now=DateTime.UtcNow;var notification=new Notification{RecipientUserId=actor,TypeCode="ADMIN_BROADCAST",PriorityCode="NORMAL",StatusCode="RECORDED",SourceTypeCode="ADMIN_BROADCAST",SourcePublicId=row.PublicId,TargetTypeCode="ADMIN_BROADCAST",TargetPublicId=row.PublicId,Title=row.Title,Body=row.Body,DataJson=JsonSerializer.Serialize(new{broadcastId=row.PublicId,row.AudienceCode,row.KindCode}),IsUrgent=false,RecordedAt=now,IdempotencyKey=$"admin-broadcast:{row.PublicId:N}"};db.Notifications.Add(notification);await db.SaveChangesAsync(token);row.NotificationId=notification.Id;row.StatusCode="QUEUED";row.ConfirmedAt=now;row.ConfirmedByUserId=actor;row.UpdatedAt=now;row.UpdatedByUserId=actor;Audit(actor,"NOTIFICATION_BROADCAST_CONFIRMED",row.PublicId,new{row.EstimatedAudienceCount,row.ScheduledAt});await db.SaveChangesAsync(token);return Item(row);}
    public async Task<NotificationBroadcastItem> Cancel(Guid id,CancelNotificationBroadcastRequest input,ClaimsPrincipal principal,string? reauth,CancellationToken token){var actor=await security.RequireSensitiveAccessAsync(Principal(principal),reauth,AdminDetailRoles.SuperAdmin,AdminDetailRoles.Operations,AdminDetailRoles.Content);var row=await db.NotificationBroadcasts.SingleOrDefaultAsync(x=>x.PublicId==id,token)??throw Error(404,"BROADCAST_NOT_FOUND","단체발송을 찾을 수 없습니다.");if(row.StatusCode is "COMPLETED" or "CANCELLED")throw Error(409,"BROADCAST_NOT_CANCELLABLE","완료되거나 취소된 발송은 변경할 수 없습니다.");Version(row,input.RowVersion);row.StatusCode="CANCELLED";row.CancelledAt=DateTime.UtcNow;row.CancelledByUserId=actor;row.CancellationReason=input.Reason.Trim();row.UpdatedAt=DateTime.UtcNow;row.UpdatedByUserId=actor;if(row.NotificationId.HasValue){var deliveries=await db.NotificationDeliveries.Where(x=>x.NotificationId==row.NotificationId&&(x.StatusCode=="PENDING"||x.StatusCode=="FAILED")).ToListAsync(token);foreach(var delivery in deliveries){delivery.StatusCode="CANCELLED";delivery.ScheduledAt=null;delivery.CompletedAt=DateTime.UtcNow;delivery.UpdatedAt=DateTime.UtcNow;}}Audit(actor,"NOTIFICATION_BROADCAST_CANCELLED",row.PublicId,new{row.CancellationReason});await db.SaveChangesAsync(token);return Item(row);}
    public async Task<(int Processed,int Created)> PrepareBatch(CancellationToken token){var row=await db.NotificationBroadcasts.Where(x=>x.StatusCode=="QUEUED"||x.StatusCode=="PREPARING").OrderBy(x=>x.ConfirmedAt).FirstOrDefaultAsync(token);if(row is null)return(0,0);row.StatusCode="PREPARING";var users=await AudienceUsers(row.AudienceCode).Where(x=>x.Id>(row.LastProcessedUserId??0)).OrderBy(x=>x.Id).Take(200).ToListAsync(token);if(users.Count==0){row.StatusCode="SENDING";row.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync(token);return(0,0);}var notificationId=row.NotificationId??throw Error(409,"BROADCAST_NOTIFICATION_MISSING","단체발송 알림 원본이 없습니다.");var channels=ParseChannels(row.ChannelsJson);var created=0;foreach(var user in users){var recipient=await db.NotificationRecipients.SingleOrDefaultAsync(x=>x.NotificationId==notificationId&&x.UserId==user.Id,token);if(recipient is null){recipient=new(){NotificationId=notificationId,UserId=user.Id,RecipientRoleCode=await RecipientRole(user.Id,row.AudienceCode,token),CreatedAt=DateTime.UtcNow};db.NotificationRecipients.Add(recipient);await db.SaveChangesAsync(token);}foreach(var channel in channels){if(await db.NotificationDeliveries.AnyAsync(x=>x.NotificationRecipientId==recipient.Id&&x.ChannelCode==channel,token))continue;var allowed=await CanDeliverAsync(row,user.Id,channel,row.ScheduledAt??DateTime.UtcNow,token);var web=allowed&&channel=="WEB";db.NotificationDeliveries.Add(new(){NotificationId=notificationId,NotificationRecipientId=recipient.Id,ChannelCode=channel,AttemptNo=1,StatusCode=web?"DELIVERED":allowed?"PENDING":"SKIPPED",ErrorCode=allowed?null:"CHANNEL_OR_CONSENT_DISABLED",ErrorMessage=allowed?null:"채널 운영 설정, 연락처 인증 또는 수신동의에 따라 발송하지 않았습니다.",ScheduledAt=allowed&&!web?(row.ScheduledAt??DateTime.UtcNow):(DateTime?)null,AttemptedAt=DateTime.UtcNow,CompletedAt=web||!allowed?DateTime.UtcNow:(DateTime?)null,DeliveredAt=web?DateTime.UtcNow:(DateTime?)null,RetryCount=0,CreatedAt=DateTime.UtcNow,UpdatedAt=DateTime.UtcNow});created++;}row.RecipientsProcessedCount++;row.LastProcessedUserId=user.Id;}row.DeliveriesCreatedCount+=created;row.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync(token);return(users.Count,created);}
    public async Task RefreshCompleted(CancellationToken token){var rows=await db.NotificationBroadcasts.Where(x=>x.StatusCode=="SENDING"&&x.NotificationId!=null).ToListAsync(token);foreach(var row in rows)if(!await db.NotificationDeliveries.AnyAsync(x=>x.NotificationId==row.NotificationId&&(x.StatusCode=="PENDING"||x.StatusCode=="PROCESSING"||(x.StatusCode=="FAILED"&&x.ScheduledAt!=null)),token)){row.StatusCode="COMPLETED";row.UpdatedAt=DateTime.UtcNow;}await db.SaveChangesAsync(token);}
    public async Task<bool> CanDeliverNotificationAsync(Notification notification,long userId,string channel,DateTime at,CancellationToken token){if(notification.SourceTypeCode!="ADMIN_BROADCAST"||notification.SourcePublicId is null)return await CanDeliverManagedAsync(notification,userId,channel,at,token);var row=await db.NotificationBroadcasts.AsNoTracking().SingleOrDefaultAsync(x=>x.PublicId==notification.SourcePublicId,token);return row is not null&&row.StatusCode!="CANCELLED"&&await CanDeliverAsync(row,userId,channel,at,token);}
    private async Task<bool> CanDeliverManagedAsync(Notification notification,long userId,string channel,DateTime at,CancellationToken token){var user=await db.Users.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==userId&&x.StatusCode=="ACTIVE",token);if(user is null)return false;var template=notification.TemplateId.HasValue?await db.NotificationTemplates.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==notification.TemplateId,token):null;if(template is null||!template.IsActive||(template.EffectiveFrom.HasValue&&template.EffectiveFrom>at)||(template.EffectiveTo.HasValue&&template.EffectiveTo<=at))return false;if(template.IsRequiredBusinessNotice&&!template.IsMarketing)return true;if((channel is "SMS" or "KAKAO")&&(user.PhoneVerificationStatusCode!="VERIFIED"||(user.Phone==null&&user.PhoneEncrypted==null)))return false;if(channel=="EMAIL"&&(user.EmailVerificationStatusCode!="VERIFIED"||(user.Email==null&&user.EmailEncrypted==null)))return false;if(channel!="WEB"){var setting=await db.NotificationChannelSettings.AsNoTracking().SingleOrDefaultAsync(x=>x.ChannelCode==channel&&x.IsEnabled,token);if(setting is null||!senders.Any(x=>x.Supports(channel)&&x.IsConfigured(channel)))return false;}var group=template.IsMarketing?"MARKETING":"BUSINESS";var preference=await db.NotificationPreferences.AsNoTracking().SingleOrDefaultAsync(x=>x.UserId==userId&&x.EventGroupCode==group&&x.WithdrawnAt==null,token);if(template.IsMarketing&&!await HasMarketingConsent(userId,token))return false;var enabled=channel switch{"WEB"=>preference?.WebEnabled??group=="BUSINESS","KAKAO"=>preference?.KakaoEnabled??false,"SMS"=>preference?.SmsEnabled??false,"EMAIL"=>preference?.EmailEnabled??false,"PUSH"=>preference?.PushEnabled??false,_=>false};if(!enabled)return false;if(template.IsMarketing){var hour=at.ToUniversalTime().AddHours(9).Hour;if((hour>=21||hour<8)&&preference?.NightMarketingEnabled!=true)return false;}return true;}
    private async Task<bool> CanDeliverAsync(NotificationBroadcast row,long userId,string channel,DateTime at,CancellationToken token){var user=await db.Users.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==userId&&x.StatusCode=="ACTIVE",token);if(user is null||!await AudienceUsers(row.AudienceCode).AnyAsync(x=>x.Id==userId,token))return false;if(channel=="KAKAO"&&row.KindCode!="BUSINESS_NOTICE")return false;if((channel is "SMS" or "KAKAO")&&(user.PhoneVerificationStatusCode!="VERIFIED"||(user.Phone==null&&user.PhoneEncrypted==null)))return false;if(channel=="EMAIL"&&(user.EmailVerificationStatusCode!="VERIFIED"||(user.Email==null&&user.EmailEncrypted==null)))return false;var setting=channel=="WEB"?null:await db.NotificationChannelSettings.AsNoTracking().SingleOrDefaultAsync(x=>x.ChannelCode==channel&&x.IsEnabled,token);if(channel!="WEB"&&(setting is null||!senders.Any(x=>x.Supports(channel)&&x.IsConfigured(channel))))return false;var group=row.KindCode=="MARKETING"?"MARKETING":"BUSINESS";var preference=await db.NotificationPreferences.AsNoTracking().SingleOrDefaultAsync(x=>x.UserId==userId&&x.EventGroupCode==group&&x.WithdrawnAt==null,token);if(row.KindCode=="MARKETING"&&!await HasMarketingConsent(userId,token))return false;var enabled=channel switch{"WEB"=>preference?.WebEnabled??row.KindCode=="BUSINESS_NOTICE","KAKAO"=>preference?.KakaoEnabled??false,"SMS"=>preference?.SmsEnabled??false,"EMAIL"=>preference?.EmailEnabled??false,"PUSH"=>preference?.PushEnabled??false,_=>false};if(!enabled)return false;if(row.KindCode=="MARKETING"){var hour=at.ToUniversalTime().AddHours(9).Hour;if((hour>=21||hour<8)&&preference?.NightMarketingEnabled!=true)return false;}return true;}
    private IQueryable<User> AudienceUsers(string audience){var roles=audience=="ALL"?new[]{RoleCodes.Customer,RoleCodes.Provider}:new[]{audience};return db.Users.AsNoTracking().Where(u=>u.StatusCode=="ACTIVE"&&db.UserRoles.Any(ur=>ur.UserId==u.Id&&ur.RevokedAt==null&&db.Roles.Any(r=>r.Id==ur.RoleId&&r.IsActive&&roles.Contains(r.Code))));}
    private Task<bool> HasMarketingConsent(long user,CancellationToken token)=>db.UserConsents.AsNoTracking().AnyAsync(c=>c.UserId==user&&c.ConsentStatusCode=="CONSENTED"&&c.WithdrawnAt==null&&db.LegalDocumentVersions.Any(v=>v.Id==c.LegalDocumentVersionId&&db.LegalDocuments.Any(d=>d.Id==v.LegalDocumentId&&(d.Code=="MARKETING_CONSENT"||d.Code=="PROVIDER_MARKETING_CONSENT"))),token);
    private async Task<string> RecipientRole(long user,string audience,CancellationToken token){if(audience!="ALL")return audience;return await(from ur in db.UserRoles.AsNoTracking()join role in db.Roles.AsNoTracking()on ur.RoleId equals role.Id where ur.UserId==user&&ur.RevokedAt==null&&(role.Code==RoleCodes.Customer||role.Code==RoleCodes.Provider)orderby role.Code==RoleCodes.Customer?0:1 select role.Code).FirstAsync(token);}
    private static void Validate(SaveNotificationBroadcastRequest input){_ = Audience(input.AudienceCode);_ = Kind(input.KindCode);_ = Channels(input);if(string.IsNullOrWhiteSpace(input.Name)||string.IsNullOrWhiteSpace(input.Title)||string.IsNullOrWhiteSpace(input.Body))throw Error(409,"BROADCAST_INPUT_REQUIRED","발송명·제목·본문을 입력해 주세요.");if(input.ScheduledAt.HasValue&&input.ScheduledAt.Value.ToUniversalTime()<DateTime.UtcNow.AddMinutes(-1))throw Error(409,"BROADCAST_SCHEDULE_INVALID","예약시간은 현재 이후로 입력해 주세요.");}
    private static string[] Channels(SaveNotificationBroadcastRequest input){var values=input.Channels.Select(x=>x.Trim().ToUpperInvariant()).Distinct().ToArray();if(values.Length==0||values.Any(x=>!AllowedChannels.Contains(x)))throw Error(409,"BROADCAST_CHANNEL_INVALID","발송 채널을 확인해 주세요.");if(input.KindCode.Trim().ToUpperInvariant()=="MARKETING"&&values.Contains("KAKAO"))throw Error(409,"BROADCAST_KAKAO_MARKETING_BLOCKED","알림톡은 정보성 공지에만 사용할 수 있습니다.");return values;}
    private static string[] ParseChannels(string json)=>JsonSerializer.Deserialize<string[]>(json)??[];private static string Audience(string value)=>value.Trim().ToUpperInvariant()is var x&&x is "CUSTOMER" or "PROVIDER" or "ALL"?x:throw Error(409,"BROADCAST_AUDIENCE_INVALID","고객·전문가·전체 중 대상을 선택해 주세요.");private static string Kind(string value)=>value.Trim().ToUpperInvariant()is var x&&x is "BUSINESS_NOTICE" or "MARKETING"?x:throw Error(409,"BROADCAST_KIND_INVALID","정보성 공지 또는 마케팅을 선택해 주세요.");
    private static NotificationBroadcastItem Item(NotificationBroadcast x)=>new(x.PublicId,x.Name,x.AudienceCode,x.KindCode,ParseChannels(x.ChannelsJson),x.Title,x.Body,x.ScheduledAt,x.StatusCode,x.EstimatedAudienceCount,x.RecipientsProcessedCount,x.DeliveriesCreatedCount,x.PreviewedAt,x.ConfirmedAt,x.CancelledAt,x.CancellationReason,x.CreatedAt,Convert.ToBase64String(x.RowVersion));
    private async Task<long> Actor(ClaimsPrincipal p,CancellationToken token)=>await db.Users.Where(x=>x.PublicId==Principal(p)&&x.StatusCode=="ACTIVE").Select(x=>x.Id).SingleAsync(token);private static Guid Principal(ClaimsPrincipal p)=>Guid.TryParse(p.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value,out var id)?id:throw Error(401,"AUTHENTICATION_REQUIRED","로그인이 필요합니다.");private static void Version(NotificationBroadcast row,string? value){if(row.RowVersion.Length==0)return;if(string.IsNullOrWhiteSpace(value))throw Error(409,"ROW_VERSION_REQUIRED","화면을 새로고침한 후 다시 시도해 주세요.");try{if(!row.RowVersion.SequenceEqual(Convert.FromBase64String(value)))throw Error(409,"ROW_VERSION_CONFLICT","다른 관리자가 먼저 변경했습니다.");}catch(FormatException){throw Error(409,"ROW_VERSION_INVALID","변경 버전을 확인해 주세요.");}}
    private async Task Save(CancellationToken token){try{await db.SaveChangesAsync(token);}catch(DbUpdateConcurrencyException){throw Error(409,"ROW_VERSION_CONFLICT","다른 관리자가 먼저 변경했습니다.");}}private void Audit(long actor,string action,Guid id,object data)=>db.AuditLogs.Add(new(){OccurredAt=DateTime.UtcNow,ActorUserId=actor,ActorRoleCode="ADMIN",ActionCode=action,EntityType="NotificationBroadcast",EntityPublicId=id,ResultCode="SUCCESS",AfterJson=JsonSerializer.Serialize(data)});private static NotificationBusinessException Error(int status,string code,string message)=>new(status,code,message);
}
